alter table public.pokoin_pokemon_expansions add column if not exists official_name text not null default '';
alter table public.pokoin_pokemon_expansions add column if not exists official_source text not null default '';
alter table public.pokoin_pokemon_expansions add column if not exists kind text not null default 'unmatched';
alter table public.pokoin_pokemon_expansions drop constraint if exists pokoin_pokemon_expansions_kind_check;
